contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {
        revert();
    }

    function run(address target, uint value) public payable {
        require(target != address(0), "target must not be zero");
        require(value <= address(c).balance, "value must not exceed c balance");

        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!reverted ? (balanceAfter == balanceBefore - value && depositsAfter == depositsBefore) : (balanceAfter == balanceBefore && depositsAfter == depositsBefore));
    }
}

