pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 value) internal {
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance);
        uint balanceBefore = address(c).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(!reverted ? (balanceAfter == balanceBefore - value && depositsAfter == depositsBefore) : (balanceAfter == balanceBefore && depositsAfter == depositsBefore));
    }

    function testFuzz_run(address target, uint256 value) public {
